{"function": "() => {
    // Find the main content area containing the rules
    const main = document.querySelector('main');
    if (!main) return null;

    // Look for the article that contains the list of rules
    const article = main.querySelector('article');
    if (!article) return null;

    // Find the list items that contain articles and rules
    // There is a list with class? Not sure, but we can find the first unordered list after the introductory paragraph.
    const lists = article.querySelectorAll('ul');
    if (lists.length === 0) return null;

    // The first ul likely contains the articles and rules
    const result = [];
    const topList = lists[0];
    const items = topList.querySelectorAll('li');

    for (const item of items) {
        // Get text content of the item, but we need structured data.
        // The item may have a direct text node (article title) and a nested ul for rules.
        const articleTitle = item.firstChild?.nodeType === Node.TEXT_NODE ? item.firstChild.textContent.trim() : '';
        const rules = [];
        const nestedUl = item.querySelector('ul');
        if (nestedUl) {
            const ruleItems = nestedUl.querySelectorAll('li');
            for (const ruleItem of ruleItems) {
                // Rule text includes link text and following text.
                const link = ruleItem.querySelector('a');
                const ruleText = ruleItem.textContent.trim();
                rules.push(ruleText);
            }
        }
        result.push({
            articleTitle,
            rules
        });
    }
    return result;
}"}

