        // Find text node that starts with ARTICLE
        for (const node of articleLi.childNodes) {
            if (node.nodeType === Node.TEXT_NODE && node.textContent.trim().startsWith('ARTICLE')) {
                articleTitle = node.textContent.trim();
                break;
