        }
        // Find nested OL
        const nestedOl = articleLi.querySelector('ol');
        const rules = [];
        if (nestedOl) {
            for (const ruleLi of nestedOl.children) {
                // ruleLi contains a link and maybe a text node after it
                let ruleText = '';
                for (const node of ruleLi.childNodes) {
                    if (node.nodeType === Node.TEXT_NODE) {
                        ruleText += node.textContent;
                    } else if (node.nodeType === Node.ELEMENT_NODE && node.tagName === 'A') {
                        ruleText += node.textContent;
                    }
                }
                ruleText = ruleText.trim();
                if (ruleText) rules.push(ruleText);
            }
        }
        articles.push({
            article: articleTitle,
            rules: rules
        });
    }
    return articles;
}"}

